/**
 * PyDict: an insertion-ordered mapping that mirrors the semantics of a CPython
 * `dict` for the subset of behaviour this port needs (string keys, iteration in
 * insertion order, `in`-style membership tests).
 *
 * A plain JS object is not good enough here because Node reorders keys that look
 * like array indices ("0", "1", "2", ...), while CPython keeps insertion order.
 * That ordering is observable in the printed output, so it has to be preserved.
 */
export class PyDict {
  constructor(entries) {
    this._map = new Map();
    if (entries) {
      for (const [key, value] of entries) {
        this.set(key, value);
      }
    }
  }

  get size() {
    return this._map.size;
  }

  set(key, value) {
    this._map.set(key, value);
    return this;
  }

  get(key) {
    return this._map.get(key);
  }

  has(key) {
    return this._map.has(key);
  }

  delete(key) {
    return this._map.delete(key);
  }

  keys() {
    return [...this._map.keys()];
  }

  values() {
    return [...this._map.values()];
  }

  entries() {
    return [...this._map.entries()];
  }

  [Symbol.iterator]() {
    return this._map.keys();
  }
}

export function isPyDict(value) {
  return value instanceof PyDict;
}

/**
 * `{f(k): g(v) for k, v in source.items()}` — a dict comprehension that keeps the
 * source ordering.
 */
export function mapValues(source, fn) {
  const result = new PyDict();
  for (const [key, value] of source.entries()) {
    result.set(key, fn(value, key));
  }
  return result;
}

