/**
 * Python integer semantics.
 *
 * CPython integers are arbitrary precision, and the reference program happily
 * multiplies user supplied values (`--a 99999999999999999999`), so every numeric
 * value in the port is a BigInt. Doubles would silently lose digits and the
 * printed diff would drift from the reference output.
 */

/** Thrown where CPython would raise ValueError from `int(...)`. */
export class PyValueError extends Error {}

// Python strips surrounding whitespace before parsing, including the unicode
// spaces that `str.strip()` treats as whitespace.
const PY_WHITESPACE = '\t\n\v\f\r   ' +
  '           ' +
  '    　';

function stripPyWhitespace(text) {
  let start = 0;
  let end = text.length;
  while (start < end && PY_WHITESPACE.includes(text[start])) start += 1;
  while (end > start && PY_WHITESPACE.includes(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

/**
 * `int(text)` for base 10: optional sign, decimal digits, and single underscore
 * separators between digits (`int('1_0') == 10`).
 */
export function pyInt(text) {
  if (typeof text !== 'string') {
    throw new PyValueError('int() argument must be a string');
  }
  const stripped = stripPyWhitespace(text);
  const match = /^([+-]?)(\d(?:_?\d)*)$/.exec(stripped);
  if (match === null) {
    throw new PyValueError(`invalid literal for int() with base 10: ${text}`);
  }
  const digits = match[2].replace(/_/g, '');
  const value = BigInt(digits);
  return match[1] === '-' ? -value : value;
}

/** `repr(int)` — plain decimal, with the sign attached to the digits. */
export function pyIntRepr(value) {
  return value.toString(10);
}

/**
 * `range(stop)` expressed as the number of iterations. Negative or zero stops
 * produce an empty range, exactly like CPython.
 */
export function rangeLength(stop) {
  return stop > 0n ? Number(stop) : 0;
}

