/** Thrown where CPython would raise ValueError from `int(...)`. */
export class PyValueError extends Error {}

// `int()` strips surrounding whitespace before parsing, using the same character
// set as `str.strip()`.
const PY_WHITESPACE = new Set([
  '\t', '\n', '\v', '\f', '\r', ' ', '', '', '', '',
  '', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', '　',
]);

function stripPyWhitespace(text) {
  let start = 0;
  let end = text.length;
  while (start < end && PY_WHITESPACE.has(text[start])) start += 1;
  while (end > start && PY_WHITESPACE.has(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

/**
 * `int(text)` for base 10: optional sign, decimal digits, and single underscore
 * separators between digits (`int('1_0') == 10`).
