import { isPyDict } from './pydict.mjs';
import { pyIntRepr } from './pyint.mjs';

/**
 * `repr()` / `str()` rendering for the value shapes this port produces, so that
 * `print(...)` of a diff result is byte-for-byte identical to CPython's.
 */

/**
 * `repr(str)`: single quotes by default, double quotes when the text contains a
 * single quote but no double quote (which is how diff paths such as
 * `root['0']` end up double quoted).
 */
export function pyReprStr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let body = '';
  for (const char of text) {
    if (char === '\\') {
      body += '\\\\';
    } else if (char === quote) {
      body += `\\${char}`;
    } else if (char === '\n') {
      body += '\\n';
    } else if (char === '\r') {
      body += '\\r';
    } else if (char === '\t') {
      body += '\\t';
    } else {
      const code = char.codePointAt(0);
      if (code < 0x20 || code === 0x7f) {
        body += `\\x${code.toString(16).padStart(2, '0')}`;
      } else {
        body += char;
      }
    }
  }
  return `${quote}${body}${quote}`;
}

/** `repr(float)` for the handful of shapes a float could take. */
export function pyReprFloat(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  if (Number.isInteger(value) && Math.abs(value) < 1e16) return `${value}.0`;
  return String(value).replace('e+', 'e+').replace(/e([+-])(\d)$/, 'e$10$2');
}

/** `repr(obj)` dispatched on the runtime shape of `obj`. */
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'bigint') return pyIntRepr(value);
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'number') return pyReprFloat(value);
  if (typeof value === 'string') return pyReprStr(value);
  if (Array.isArray(value)) {
    return `[${value.map(pyRepr).join(', ')}]`;
  }
  if (isPyDict(value)) {
    const body = value
      .entries()
      .map(([key, item]) => `${pyRepr(key)}: ${pyRepr(item)}`)
      .join(', ');
    return `{${body}}`;
  }
  if (typeof value.__repr__ === 'function') return value.__repr__();
  return String(value);
}

/** `str(obj)`; identical to `repr` for every type used here. */
export function pyStr(value) {
  if (typeof value === 'string') return value;
  if (value !== null && value !== undefined && typeof value.__str__ === 'function') {
    return value.__str__();
  }
  return pyRepr(value);
}

/** `print(value)` on stdout. */
export function pyPrint(value) {
  console.log(pyStr(value));
}

