import { basename } from 'node:path';
import { pyInt, PyValueError } from './pyint.mjs';
import { pyReprStr } from './pyrepr.mjs';

/**
 * A minimal stand-in for the slice of `argparse` the reference program uses:
 * long options that each take exactly one value, `type=int`, `required=True`,
 * the automatic `-h/--help` action, prefix abbreviation, and the usage/error
 * formatting (including the exit status 2 on a parse error).
 */

/** `type=int` for `add_argument`. */
export const INT_TYPE = { name: 'int', convert: pyInt };

/** `type=str` (argparse's default: the raw string is passed through). */
export const STR_TYPE = { name: 'string', convert: (text) => text };

// argparse only refuses to treat a leading-dash token as a value when it really
// looks like an option: bare "-" and negative numbers are values, and so is any
// token containing a space.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOption(token) {
  if (token.length === 0 || token[0] !== '-') return false;
  if (token === '-' || token === '--') return token === '--';
  if (NEGATIVE_NUMBER.test(token)) return false;
  if (token.includes(' ')) return false;
  return true;
}

class Action {
  constructor({ optionStrings, dest, type, required, help, isHelp = false }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type;
    this.required = required;
    this.help = help;
    this.isHelp = isHelp;
    this.metavar = isHelp ? null : dest.toUpperCase();
  }

  /** argparse's `_get_action_name`: option strings joined with a slash. */
  get name() {
    return this.optionStrings.join('/');
  }

  /** How the action appears in usage and in the options list. */
  formatInvocation() {
    if (this.isHelp) return this.optionStrings.join(', ');
    return this.optionStrings.map((option) => `${option} ${this.metavar}`).join(', ');
  }

  formatUsagePart() {
    const body = this.isHelp
      ? this.optionStrings[0]
      : `${this.optionStrings[0]} ${this.metavar}`;
    return this.required ? body : `[${body}]`;
  }
}

const HELP_INDENT = 2;
const MAX_HELP_POSITION = 24;

export class ArgumentParser {
  constructor(options = {}) {
    const scriptPath = process.argv[1];
    this.prog = options.prog ?? (scriptPath ? basename(scriptPath) : 'prog');
    this.actions = [];
    if (options.add_help !== false) {
      this.actions.push(new Action({
        optionStrings: ['-h', '--help'],
        dest: 'help',
        type: null,
        required: false,
        help: 'show this help message and exit',
        isHelp: true,
      }));
    }
  }

  add_argument(name, options = {}) {
    const optionStrings = Array.isArray(name) ? name : [name];
    const primary = optionStrings.find((option) => option.startsWith('--')) ?? optionStrings[0];
    const dest = options.dest ?? primary.replace(/^--?/, '').replace(/-/g, '_');
    const action = new Action({
      optionStrings,
      dest,
      type: options.type ?? STR_TYPE,
      required: options.required === true,
      help: options.help ?? null,
    });
    this.actions.push(action);
    return action;
  }

  format_usage() {
    const parts = this.actions.map((action) => action.formatUsagePart());
    return `usage: ${this.prog}${parts.length ? ' ' : ''}${parts.join(' ')}\n`;
  }

  format_help() {
    const invocations = this.actions.map((action) => action.formatInvocation());
    const actionMaxLength = invocations.reduce(
      (longest, invocation) => Math.max(longest, invocation.length + HELP_INDENT),
      0,
    );
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);

    let help = this.format_usage();
    help += '\noptions:\n';
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      if (!action.help) {
        help += `${' '.repeat(HELP_INDENT)}${invocation}\n`;
      } else if (invocation.length + HELP_INDENT + 2 <= helpPosition) {
        const padded = invocation.padEnd(helpPosition - HELP_INDENT);
        help += `${' '.repeat(HELP_INDENT)}${padded}${action.help}\n`;
      } else {
        help += `${' '.repeat(HELP_INDENT)}${invocation}\n`;
        help += `${' '.repeat(helpPosition)}${action.help}\n`;
      }
    });
    return help;
  }

  print_help() {
    process.stdout.write(this.format_help());
  }

  /** argparse's `error()`: usage plus message on stderr, then exit code 2. */
  error(message) {
    process.stderr.write(this.format_usage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** Resolve a typed option string, honouring argparse's prefix abbreviation. */
  _matchOption(token) {
    const exact = this.actions.find((action) => action.optionStrings.includes(token));
    if (exact) return { action: exact, ambiguous: null };
    if (!token.startsWith('--')) return { action: null, ambiguous: null };
    const candidates = [];
    for (const action of this.actions) {
      for (const option of action.optionStrings) {
        if (option.startsWith('--') && option.startsWith(token)) {
          candidates.push({ action, option });
        }
      }
    }
    if (candidates.length === 1) return { action: candidates[0].action, ambiguous: null };
    if (candidates.length > 1) {
      return { action: null, ambiguous: candidates.map((entry) => entry.option) };
    }
    return { action: null, ambiguous: null };
  }

  parse_args(argv = process.argv.slice(2)) {
    const values = new Map();
    const extras = [];
    let positionalsOnly = false;

    for (let index = 0; index < argv.length; index += 1) {
      const token = argv[index];

      if (positionalsOnly || !looksLikeOption(token)) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        positionalsOnly = true;
        continue;
      }

      let optionString = token;
      let explicitValue = null;
      const equals = token.indexOf('=');
      if (token.startsWith('--') && equals !== -1) {
        optionString = token.slice(0, equals);
        explicitValue = token.slice(equals + 1);
      }

      const { action, ambiguous } = this._matchOption(optionString);
      if (ambiguous) {
        this.error(`ambiguous option: ${optionString} could match ${ambiguous.join(', ')}`);
      }
      if (!action) {
        extras.push(token);
        continue;
      }
      if (action.isHelp) {
        this.print_help();
        process.exit(0);
      }

      let raw = explicitValue;
      if (raw === null) {
        const next = argv[index + 1];
        if (next === undefined || looksLikeOption(next)) {
          this.error(`argument ${action.name}: expected one argument`);
        }
        raw = next;
        index += 1;
      }

      try {
        values.set(action.dest, action.type.convert(raw));
      } catch (problem) {
        if (problem instanceof PyValueError) {
          this.error(
            `argument ${action.name}: invalid ${action.type.name} value: ${pyReprStr(raw)}`,
          );
        }
        throw problem;
      }
    }

    // argparse reports missing required arguments before unrecognized ones.
    const missing = this.actions
      .filter((action) => action.required && !values.has(action.dest))
      .map((action) => action.name);
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    const namespace = {};
    for (const action of this.actions) {
      if (action.isHelp) continue;
      namespace[action.dest] = values.has(action.dest) ? values.get(action.dest) : null;
    }
    return namespace;
  }
}

