import { pyRepr } from '../pyrepr.mjs';

/**
 * Diff paths, rendered the way DeepDiff's text view renders them: the root object
 * is `root`, and every step down a mapping or sequence is a subscript, e.g.
 * `root['3']` or `root[0]`.
 */

export const ROOT_PATH = 'root';

/** Extend a path with a mapping/sequence subscript. */
export function childPath(parentPath, key) {
  return `${parentPath}[${pyRepr(key)}]`;
}

