import { isPyDict } from '../pydict.mjs';
import { childPath, ROOT_PATH } from './path.mjs';
import { DiffResult } from './result.mjs';

/**
 * The diffing engine.
 *
 * Behaviour reproduced from the reference implementation:
 *  - mappings are compared key by key: keys only in the right hand side land in
 *    `dictionary_item_added`, keys only in the left hand side in
 *    `dictionary_item_removed`, and shared keys are recursed into;
 *  - when the two mappings barely overlap, the whole level is reported as a
 *    single `values_changed` entry instead of being diffed key by key. The
 *    trigger is the shared-key ratio: with more than one key in the union of
 *    both key sets, an overlap below `threshold_to_diff_deeper` (0.33) collapses
 *    the level. That is why `{} vs {'0': 0}` still reports an added key (union of
 *    one) while `{} vs {'0': 0, '1': 1}` collapses to a root value change;
 *  - values that differ produce `values_changed` with `new_value` before
 *    `old_value`; values whose types differ produce `type_changes`.
 */

const DEFAULT_THRESHOLD_TO_DIFF_DEEPER = 0.33;

/** The name `type(obj).__name__` would give for the values used here. */
export function pyTypeName(value) {
  if (value === null || value === undefined) return 'NoneType';
  if (typeof value === 'bigint') return 'int';
  if (typeof value === 'boolean') return 'bool';
  if (typeof value === 'number') return 'float';
  if (typeof value === 'string') return 'str';
  if (Array.isArray(value)) return 'list';
  if (isPyDict(value)) return 'dict';
  return 'object';
}

function scalarsEqual(left, right) {
  return left === right;
}

class Differ {
  constructor(options) {
    this.result = new DiffResult();
    this.thresholdToDiffDeeper = options.threshold_to_diff_deeper ??
      DEFAULT_THRESHOLD_TO_DIFF_DEEPER;
  }

  diff(t1, t2, path) {
    if (t1 === t2) return;

    const leftType = pyTypeName(t1);
    const rightType = pyTypeName(t2);
    if (leftType !== rightType) {
      this.result.addTypeChange(path, t1, t2, leftType, rightType);
      return;
    }

    if (leftType === 'dict') {
      this.diffDict(t1, t2, path);
    } else if (leftType === 'list') {
      this.diffList(t1, t2, path);
    } else if (!scalarsEqual(t1, t2)) {
      this.result.addChange('values_changed', path, t1, t2);
    }
  }

  diffDict(t1, t2, path) {
    const leftKeys = t1.keys();
    const rightKeys = t2.keys();
    const leftKeySet = new Set(leftKeys);
    const rightKeySet = new Set(rightKeys);

    const shared = rightKeys.filter((key) => leftKeySet.has(key));
    const added = rightKeys.filter((key) => !leftKeySet.has(key));
    const removed = leftKeys.filter((key) => !rightKeySet.has(key));
    const unionSize = shared.length + added.length + removed.length;

    if (
      this.thresholdToDiffDeeper &&
      unionSize > 1 &&
      shared.length / unionSize < this.thresholdToDiffDeeper
    ) {
      this.result.addChange('values_changed', path, t1, t2);
      return;
    }

    for (const key of added) {
      this.result.addPath('dictionary_item_added', childPath(path, key));
    }
    for (const key of removed) {
      this.result.addPath('dictionary_item_removed', childPath(path, key));
    }
    for (const key of shared) {
      this.diff(t1.get(key), t2.get(key), childPath(path, key));
    }
  }

  diffList(t1, t2, path) {
    const shared = Math.min(t1.length, t2.length);
    for (let index = 0; index < shared; index += 1) {
      this.diff(t1[index], t2[index], childPath(path, BigInt(index)));
    }
    for (let index = shared; index < t2.length; index += 1) {
      this.result.addChange('iterable_item_added', childPath(path, BigInt(index)), undefined, t2[index]);
    }
    for (let index = shared; index < t1.length; index += 1) {
      this.result.addChange('iterable_item_removed', childPath(path, BigInt(index)), t1[index], undefined);
    }
  }
}

/** `DeepDiff(t1, t2)` — returns the text view of the differences. */
export function DeepDiff(t1, t2, options = {}) {
  const differ = new Differ(options);
  differ.diff(t1, t2, ROOT_PATH);
  return differ.result;
}

